-- ============================================================
-- RideShare SQL Dataset — DDL
-- Standard SQL (SQLite / PostgreSQL / MySQL compatible)
-- ============================================================

CREATE TABLE IF NOT EXISTS users (
    user_id     INTEGER PRIMARY KEY,
    name        VARCHAR(100)  NOT NULL,
    email       VARCHAR(150)  NOT NULL UNIQUE,
    phone       VARCHAR(20),
    city        VARCHAR(80),
    date_joined DATE,
    is_driver   INTEGER       NOT NULL DEFAULT 0  -- 0=false, 1=true
);

CREATE TABLE IF NOT EXISTS drivers (
    driver_id     INTEGER PRIMARY KEY,
    user_id       INTEGER NOT NULL REFERENCES users(user_id),
    vehicle_make  VARCHAR(50),
    vehicle_model VARCHAR(50),
    vehicle_year  INTEGER,
    license_plate VARCHAR(20) UNIQUE,
    rating        REAL,
    join_date     DATE,
    is_active     INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS riders (
    rider_id    INTEGER PRIMARY KEY,
    user_id     INTEGER NOT NULL REFERENCES users(user_id),
    rating      REAL,
    total_trips INTEGER NOT NULL DEFAULT 0,
    created_at  DATETIME
);

CREATE TABLE IF NOT EXISTS locations (
    location_id INTEGER PRIMARY KEY,
    zone_name   VARCHAR(100),
    city        VARCHAR(80),
    latitude    REAL,
    longitude   REAL,
    zone_type   VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS trips (
    trip_id              INTEGER PRIMARY KEY,
    rider_id             INTEGER NOT NULL REFERENCES riders(rider_id),
    driver_id            INTEGER NOT NULL REFERENCES drivers(driver_id),
    pickup_location_id   INTEGER NOT NULL REFERENCES locations(location_id),
    dropoff_location_id  INTEGER NOT NULL REFERENCES locations(location_id),
    requested_at         DATETIME,
    started_at           DATETIME,
    completed_at         DATETIME,
    status               VARCHAR(20),
    distance_km          REAL,
    duration_mins        INTEGER,
    base_fare            REAL,
    surge_multiplier     REAL,
    total_fare           REAL,
    payment_method       VARCHAR(20)
);

CREATE TABLE IF NOT EXISTS payments (
    payment_id INTEGER PRIMARY KEY,
    trip_id    INTEGER NOT NULL REFERENCES trips(trip_id),
    amount     REAL,
    method     VARCHAR(20),
    status     VARCHAR(20),
    paid_at    DATETIME
);

CREATE TABLE IF NOT EXISTS reviews (
    review_id   INTEGER PRIMARY KEY,
    trip_id     INTEGER NOT NULL REFERENCES trips(trip_id),
    reviewer_id INTEGER NOT NULL REFERENCES users(user_id),
    reviewee_id INTEGER NOT NULL REFERENCES users(user_id),
    rating      INTEGER,
    comment     TEXT,
    reviewed_at DATETIME
);

CREATE TABLE IF NOT EXISTS cancellations (
    cancel_id    INTEGER PRIMARY KEY,
    trip_id      INTEGER NOT NULL REFERENCES trips(trip_id),
    cancelled_by VARCHAR(10),
    reason       VARCHAR(100),
    cancelled_at DATETIME
);

